/**
 * Handles Git actions (commits and modifications) and triggers analysis
 * 
 * @param repo - Git repository object
 * @param action - Type of Git action (COMMIT or MODIFY)
 * @param data - Action-specific data
 * @param op - Output channel for logging
 */
async function handleGitAction(
  repo: any,
  action: "COMMIT" | "MODIFY",
  data: any,
  op: vscode.OutputChannel
) {
  if (action === "COMMIT") {
    // Reset threshold tracking when user commits
    resetThresholdTracking();
    op?.appendLine(" Threshold tracking reset due to commit");
    
    showCommitAnalysisUI(repo, data.commitHash, op);

    try {
      const payload = await analyzeCommittedChanges(repo, data.commitHash, op);
      op.appendLine("commit payload " + JSON.stringify(payload, null, 2));
    } catch (err) {
      // Ignore analysis errors
    }

    try {
      appInsights?.trackTrace({
        message: "Git commit detected",
        properties: {
          action: "COMMIT",
          commitHash: data.commitHash.substring(0, 8),
          repoPath: repo.rootUri.fsPath,
          timestamp: new Date().toISOString(),
        },
        severityLevel: 0,
      });
    } catch (error) {
      // Ignore logging errors
    }
  } else if (action === "MODIFY") {
    try {
      const analysisPayload = await analyzeUncommittedChanges(repo, op);
      op.appendLine("modify payload is here" + JSON.stringify(analysisPayload, null, 2));

      // ✅ FIXED: Calculate total changed lines from current diff
      let currentChangedLines = 0;
      for (const file of analysisPayload.files) {
        if (file.patch) {
          const fileChanges = countChangedLinesInPatch(file.patch);
          currentChangedLines += fileChanges;
          op?.appendLine(`📄 File ${file.filename}: ${fileChanges} lines changed`);
        }
      }

      // ✅ FIXED: Add current changes to cumulative total (PERSISTENT tracking)
      cumulativeChangedLines += currentChangedLines;
      op?.appendLine(`📊 Cumulative changed lines: ${cumulativeChangedLines}, Last threshold: ${lastThresholdCrossed}`);

      // ✅ FIXED: Find the next threshold that hasn't been crossed yet
      const nextThreshold = thresholds.find(
        (t) => cumulativeChangedLines >= t.limit && t.limit > lastThresholdCrossed
      );

      op?.appendLine(`🔍 Checking thresholds: cumulativeLines=${cumulativeChangedLines}, lastCrossed=${lastThresholdCrossed}`);
      thresholds.forEach((t) => {
        const shouldTrigger = cumulativeChangedLines >= t.limit && t.limit > lastThresholdCrossed;
        op?.appendLine(`  Threshold ${t.limit}: shouldTrigger=${shouldTrigger}`);
      });

      if (nextThreshold) {
        op?.appendLine(`✅ Found next threshold: ${nextThreshold.limit}`);
        
        const choice = await vscode.window.showInformationMessage(
          nextThreshold.message,
          "Analyze",
          "Cancel"
        );

        if (choice === "Analyze") {
          try {
            await vscode.commands.executeCommand("workbench.view.extension.CodeSherlock");
          } catch (err: any) {
            vscode.window.showErrorMessage("Unable to open CodeSherlock sidebar view.");
          }

          await sendToAnalysisPipeline(analysisPayload, false, true, op);
          lastThresholdCrossed = nextThreshold.limit;
          op?.appendLine(`✅ Threshold ${nextThreshold.limit} crossed and analysis triggered`);
        } else if (choice === "Cancel") {
          // ✅ FIXED: Only reset if user explicitly cancels, but keep cumulative count
          // Don't reset cumulativeChangedLines, just update the last threshold crossed
          lastThresholdCrossed = nextThreshold.limit;
          op?.appendLine(`❌ User cancelled analysis for threshold ${nextThreshold.limit}`);
        }
      } else {
        // No new threshold reached, just send for background processing
        await sendToAnalysisPipeline(analysisPayload, false, false, op);
      }
    } catch (error) {
      // Ignore analysis errors
    }
  }
}

