  setupRepositoryWatching,
  handleGitAction,
  showCommitAnalysisUI,
  getCommitAnalysisData,
  mapGitStatus,
  getFileContent,
  getPatchData,
  generateAlternativeDiff,
  generateEnhancedDiff,
  sendToAnalysisPipeline,
  getRepoMetadata,
  resetThresholdTracking,
