  try {
    const latestCommit = execSync("git rev-parse HEAD", {
      cwd: vscode.workspace.workspaceFolders?.[0]?.uri.fsPath ?? undefined,
    }).toString().trim();
    return latestCommit;
  } catch (err) {
    throw new Error(`Could not retrieve latest commit: ${err.message}`);
  }
