async function getGitRepository(): Promise<any | undefined> {
  const gitExtension = vscode.extensions.getExtension("vscode.git")?.exports;
  const git = gitExtension?.getAPI(1);
  const repos = git?.repositories;
  if (repos && repos.length > 0) {
    return repos[0];
  }
  return undefined;
}
/**
 * Enhanced uncommitted changes analysis with improved repository handling
 * 
 * @param repo - Git repository object
 * @returns AnalysisPayload with enhanced uncommitted changes analysis
 */
async function analyzeUncommittedChangesEnhanced(repo: any): Promise<AnalysisPayload> {
  const meta = getRepoMetadata(repo);
  let files: any[] = [];
  let diffChanges: any[] = [];

  try {
    try {
      diffChanges = await repo.diffWithHEAD();
    } catch { }

    if (diffChanges.length === 0) {
      try {
        const indexChanges = await repo.diffIndexWithHEAD();
        diffChanges = indexChanges;
      } catch { }
    }

    if (diffChanges.length === 0) {
      const workingChanges = repo.state?.workingTreeChanges || [];
      const indexChanges = repo.state?.indexChanges || [];
      diffChanges = [...workingChanges, ...indexChanges];
    }

    if (diffChanges.length === 0) {
      try {
        const allChanges = await repo.diffWithHEAD();
        diffChanges = allChanges;
      } catch { }
    }

    if (diffChanges.length > 0) {
      for (const change of diffChanges) {
        try {
          const filename = getSafeFilenameEnhanced(change);
          const status = mapGitStatus(change.status);
          const new_content = await getFileContent(change.uri, status);
          const patch = await getPatchData(repo, change, repo.state?.HEAD?.commit || "", "");
          files.push({ filename, status, new_content, patch });
        } catch { }
      }
    }

    return {
      ...meta,
      commitId: repo.state?.HEAD?.commit || "",
      files,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : String(err);
    return {
      ...meta,
      files: [],
      error: errorMsg
    };
  }
}

function getSafeFilenameEnhanced(change: any): string {
  try {
    if (change.uri && change.uri.fsPath) {
      return vscode.workspace.asRelativePath(change.uri);
    } else if (change.uri && change.uri.path) {
      const fullPath = change.uri.path;
      const pathParts = fullPath.split(/[/\\]/);
      return pathParts[pathParts.length - 1];
    } else if (change.uri && typeof change.uri === 'string') {
      const pathParts = change.uri.split(/[/\\]/);
      return pathParts[pathParts.length - 1];
    } else {
      return 'unknown-file';
    }
  } catch {
    return 'error-file';
  }
}

function resetThresholdTracking(op?: vscode.OutputChannel) {
  lastThresholdCrossed = 0;
  cumulativeChangedLines = 0;
  op?.appendLine(" Threshold tracking reset - starting fresh");
}

